def is_blocked_very_fast(diff):
    for p in small_primes:
        if diff % p == _sage_const_0 :
            if diff % (p*p) != _sage_const_0 :
                return p
    return None

def check_candidate_very_fast(N):
    N2 = N * N
    V_actual = [v for v in all_V if v < N2]
    
    for v in V_actual:
        p = is_blocked_very_fast(N2 - v)
        if p is None:
            return False
    return True

def confirm_candidate(N):
    N2 = N * N
    V_actual = [v for v in all_V if v < N2]
    
    blocking_primes = {}
    for v in V_actual:
        diff = N2 - v
        factors = factor(diff)
        found_p = None
        for p, exp in factors:
            if p % _sage_const_4  == _sage_const_3  and exp % _sage_const_2  != _sage_const_0 :
                found_p = int(p)
                break
        if found_p is None:
            return None
            
        if diff % found_p == _sage_const_0  and diff % (found_p*found_p) != _sage_const_0 :
            blocking_primes[v] = found_p
        else:
            success_v = False
            for q, e in factors:
                if q % _sage_const_4  == _sage_const_3  and e % _sage_const_2  != _sage_const_0 :
                    if diff % q == _sage_const_0  and diff % (q*q) != _sage_const_0 :
                        blocking_primes[v] = int(q)
                        success_v = True
                        break
            if not success_v:
                return None
    return blocking_primes

def worker(worker_id, k_start, k_end, shutdown_event):
    if worker_id == _sage_const_0 :
        print(f"Worker 0 starting loop from k = {k_start}", flush=True)
    
    last_print = time.time()
    for k in range(k_start, k_end):
        if shutdown_event.is_set():
            break
            
        N = N0 + k * base_prod
        if N <= _sage_const_1 :
            continue
        if N >= _sage_const_1p27  * _sage_const_10 **_sage_const_24 :
            break
            
        if worker_id == _sage_const_0  and time.time() - last_print > _sage_const_15 :
            print(f"Worker 0 at k = {k}, N = {N}... elapsed: {time.time() - start_time_global:.2f}s", flush=True)
            last_print = time.time()
            
        if check_candidate_very_fast(N):
            bp = confirm_candidate(N)
            if bp is not None:
                print(f"\nSUCCESS! Worker {worker_id} found counterexample N = {N} (k = {k})", flush=True)
                print(f"N^2 = {N*N}", flush=True)
                print(f"V_all size = {len([v for v in all_V if v < N*N])}", flush=True)
                print(f"blocking_primes = {bp}", flush=True)
                
                with open("/workspace/leanproject/Submission/success_sage_found.py", "w") as f:
                    f.write(f"N = {N}\n")
                    f.write(f"blocking_primes = {bp}\n")
                shutdown_event.set()
                break

if __name__ == "__main__":
    k_max = _sage_const_20000000 
    num_workers = _sage_const_32 
    step = k_max // num_workers
    
    shutdown_event = Event()
    processes = []
    
    start_time_global = time.time()
    
    for i in range(num_workers):
        w_start = i * step
        w_end = (i+_sage_const_1 ) * step if i < num_workers - _sage_const_1  else k_max
        p = Process(target=worker, args=(i, w_start, w_end, shutdown_event))
        processes.append(p)
        p.start()
        
    try:
        while not shutdown_event.is_set():
            alive = False
            for p in processes:
                if p.is_alive():
                    alive = True
                    break
            if not alive:
                print("All processes finished search.", flush=True)
                break
            time.sleep(_sage_const_1 )
    except KeyboardInterrupt:
        print("Interrupted! Terminating processes...")
        shutdown_event.set()
        
    for p in processes:
        p.join(timeout=_sage_const_1 )
        if p.is_alive():
            p.terminate()
            
    print(f"Done in {time.time() - start_time_global:.2f}s.", flush=True)

